date_default_timezone_set('America/Sao_Paulo');
$atualizado = $DADOS['atualizado'];
// só pacotes com saída de hoje em diante
$pacotes = array_values(array_filter($DADOS['pacotes'], function ($x) { return implode('-', array_reverse(explode('/', $x[3]))) >= date('Y-m-d'); }));
// intercala destinos (1 de cada, depois o 2º de cada...) para a vitrine não repetir cidade
$grp = []; foreach ($pacotes as $x) $grp[$x[1]][] = $x;
$pacotes = []; for ($i = 0; $grp; $i++) foreach ($grp as $d => $l) { if (isset($l[$i])) $pacotes[] = $l[$i]; else unset($grp[$d]); }
$destNomes = array_values(array_unique(array_column($pacotes, 1))); sort($destNomes);
// resumo por destino: quantidade e menor preço
$res = []; foreach ($pacotes as $x) { $r = &$res[$x[1]]; $r['n'] = ($r['n'] ?? 0) + 1; $r['min'] = min($r['min'] ?? PHP_INT_MAX, $x[5]); unset($r); }
$base = []; foreach (array_keys($res) as $k) $base[preg_replace('/ - [^-]+$/u', '', $k)] = $k;   // 'Gramado - RS' => 'Gramado'
$destinos = []; foreach ($DADOS['destinos'] as $d) if (isset($base[$d[0]])) { $k = $base[$d[0]]; $destinos[] = array_merge($d, [$res[$k]['n'], $res[$k]['min'], $k]); }
usort($destinos, function ($a, $b) { return $b[4] <=> $a[4]; });
// hospedagens intercaladas por destino
$grp = []; foreach ($DADOS['hoteis'] as $h) $grp[$h[1]][] = $h;
$hoteis = []; for ($i = 0; $grp; $i++) foreach ($grp as $d => $l) { if (isset($l[$i])) $hoteis[] = $l[$i]; else unset($grp[$d]); }
$hotDest = array_values(array_unique(array_column($hoteis, 1))); sort($hotDest);
$experiencias = $DADOS['experiencias'];
$vantagens = [
