/* sobre */
.about{display:grid;grid-template-columns:.8fr 1.2fr;gap:56px;align-items:center}
.pic{position:relative;border-radius:28px;overflow:hidden;aspect-ratio:4/5;background:linear-gradient(135deg,var(--c1),var(--c3));display:grid;place-items:center;box-shadow:0 24px 50px rgba(11,42,74,.25)}
.pic img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.pic span{font:700 7rem var(--serif);color:rgba(255,255,255,.9)}
.sig{margin-top:22px;padding-left:16px;border-left:4px solid var(--c2)}
.sig b{display:block;font:700 1.3rem var(--serif);color:var(--c1)}
.sig span{color:var(--mut);font-size:.92rem}
.about p{color:var(--mut);margin-bottom:14px;font-size:1.04rem}
.vant{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}
.v{background:#fff;padding:26px;border-radius:var(--r);box-shadow:0 6px 22px rgba(11,42,74,.07);border-top:4px solid var(--c3)}
.v b{display:block;font:700 1.15rem var(--serif);color:var(--c1);margin-bottom:6px}
.v p{color:var(--mut);font-size:.95rem}
.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:28px;counter-reset:s}
.st{text-align:center;padding:10px}
.st:before{counter-increment:s;content:counter(s);display:grid;place-items:center;width:58px;height:58px;margin:0 auto 14px;border-radius:50%;background:var(--c2);color:#fff;font:700 1.5rem var(--serif)}
.st b{display:block;font-size:1.1rem;color:var(--c1);margin-bottom:4px}
.st p{color:var(--mut);font-size:.94rem}
details{background:#fff;border-radius:14px;padding:18px 22px;margin-bottom:12px;box-shadow:0 4px 16px rgba(11,42,74,.07)}
summary{cursor:pointer;font-weight:600;color:var(--c1);list-style:none;display:flex;justify-content:space-between}
summary:after{content:"+";font-size:1.4rem;line-height:1;color:var(--c2)}
details[open] summary:after{content:"–"}
details p{margin-top:10px;color:var(--mut)}
.final{background:linear-gradient(120deg,rgba(11,42,74,.92),rgba(11,42,74,.7)),url("<?= e(img('1500375592092-40eb2168fd21',1800,900)) ?>") center/cover,var(--c1);color:#fff;text-align:center}
.final h2{font:700 clamp(1.9rem,4vw,3rem)/1.15 var(--serif);margin-bottom:14px}
.final p{opacity:.9;max-width:560px;margin:0 auto 26px}
footer{background:#07182b;color:#9fb0c3;padding:52px 0 28px;font-size:.92rem}
footer .w{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:34px}
footer b{color:#fff;display:block;margin-bottom:10px}
footer a:hover{color:#fff}
.copy{border-top:1px solid #1c3048;margin-top:30px;padding-top:20px;text-align:center;font-size:.82rem;grid-column:1/-1}
.dev{grid-column:1/-1;text-align:center;font-size:.82rem}.dev a{display:inline-flex;align-items:center;gap:8px;padding:8px 18px;border:1px solid #1c3048;border-radius:999px;transition:.2s}.dev a:hover{border-color:var(--c3);color:#fff}.dev svg{width:16px;height:16px;fill:var(--c3)}.dev b{color:#fff;letter-spacing:.5px}
.zap{position:fixed;right:20px;bottom:20px;z-index:60;width:62px;height:62px;border-radius:50%;background:#25d366;display:grid;place-items:center;box-shadow:0 6px 20px rgba(0,0,0,.3);animation:pu 2.4s infinite}
.zap svg{width:34px;height:34px;fill:#fff}
@keyframes pu{0%{box-shadow:0 0 0 0 rgba(37,211,102,.6)}70%{box-shadow:0 0 0 18px rgba(37,211,102,0)}100%{box-shadow:0 0 0 0 rgba(37,211,102,0)}}
.rv{opacity:0;transform:translateY(26px);transition:opacity .7s,transform .7s}
.rv.in{opacity:1;transform:none}
@media(max-width:900px){
 nav{position:fixed;inset:74px 0 auto 0;background:var(--c1);flex-direction:column;gap:0;padding:8px 22px 20px;display:none}
 nav.open{display:flex}nav a{padding:14px 0;border-bottom:1px solid #1c3a5c}
 .menu{display:block}header .btn{display:none}
 .hero .w,.about,footer .w{grid-template-columns:1fr}
 .dest p{opacity:.92;max-height:120px}
 section{padding:64px 0}
}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.rv{opacity:1;transform:none}}
