<script>
(function(){
  var h=document.getElementById('top');
  function s(){h.classList.toggle('on',scrollY>40)} s(); addEventListener('scroll',s,{passive:true});
  document.querySelectorAll('#nav a').forEach(function(a){a.onclick=function(){document.getElementById('nav').classList.remove('open')}});
  // pacotes: filtro Brasil/Internacional, destino e "ver mais"
  var tabs=document.querySelectorAll('.tabs button'),cards=document.querySelectorAll('.pc'),mais=document.getElementById('mais'),cat='',dst='',lim=12;
  function ap(){var n=0,t=0;cards.forEach(function(c){var ok=(!cat||c.dataset.c===cat)&&(!dst||c.dataset.d===dst);if(ok)t++;var v=ok&&n<lim;if(v)n++;c.classList.toggle('h',!v)});mais.style.display=t>lim?'':'none'}
  function aba(f){tabs.forEach(function(x){x.classList.toggle('a',x.dataset.f===f)})}
  tabs.forEach(function(b){b.onclick=function(){cat=b.dataset.f;dst='';lim=12;aba(cat);ap()}});
  mais.onclick=function(){lim+=12;ap()}; ap();
  document.querySelectorAll('[data-go]').forEach(function(a){a.onclick=function(){dst=a.dataset.go;cat='';lim=12;aba('');ap()}});
  // hospedagens: filtro por destino e "ver mais"
  var hs=document.querySelectorAll('.hc'),hsel=document.getElementById('hsel'),hm=document.getElementById('hmais'),hl=12;
  function hap(){var n=0,t=0,v=hsel.value;hs.forEach(function(c){var ok=!v||c.dataset.d===v;if(ok)t++;var s=ok&&n<hl;if(s)n++;c.classList.toggle('h',!s)});hm.style.display=t>hl?'':'none'}
  if(hsel){hsel.onchange=function(){hl=12;hap()};hm.onclick=function(){hl+=12;hap()};hap()}
  // aparecer ao rolar
  var els=document.querySelectorAll('.rv');
  if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:.12});
    els.forEach(function(el){io.observe(el)});
  } else els.forEach(function(el){el.classList.add('in')});
})();
function orcar(f){
  var d=function(v){if(!v)return'a definir';var p=v.split('-');return p[2]+'/'+p[1]+'/'+p[0]};
  var m='Olá! Meu nome é '+f.nome.value+'.\nQuero um orçamento de viagem.\nDestino: '+f.dest.value+
        '\nIda: '+d(f.ini.value)+'\nVolta: '+d(f.fim.value)+'\nAdultos: '+f.ad.value+'\nCrianças: '+f.cr.value;
  location.href='https://wa.me/<?= e($C['whats']) ?>?text='+encodeURIComponent(m);
  return false;
}
</script>
